description:
[Bug] [Relax VM] All of Arguments of SetInput will be Convert to The 1st Device
tvm/src/runtime/relax_vm/vm.cc Lines 510 to 531 in 299ef81 void VirtualMachineImpl::SetInput(std::string func_name, bool with_param_module, TVMArgs args) { const auto& m = exec_->func_map; if (m.find(func_name) != m.end()) { Index gf_idx = m.at(func_name); const VMFuncInfo& vm_func = exec_->func_table[gf_idx]; size_t params_num = vm_func.num_args; ICHECK_EQ(args.size(), params_num) << "The number of provided parameters doesn't match the number of arguments for"; std::vector<RegType> func_args(params_num); for (int i = 0; i < args.size(); ++i) { if (with_param_module && i == args.size() - 1) { // call param func to get the arguments(usually corresponds to param pack.) func_args[i] = (args[i].operator Module()).GetFunction("get_params")(); } else { func_args[i] = ConvertArgToDevice(args[i], devices[0], allocators[0]); } } inputs_[func_name] = func_args; } else { LOG(FATAL) << "ValueError: Unknown function: " << func_name; } } tvm/src/runtime/relax_vm/vm.cc Line 524 in 299ef81 func_args[i] = ConvertArgToDevice(args[i], devices[0], allocators[0]); Why all of the arguments given to "SetInput" will be convert to the 1st device? Is it a typo? I think it should be something below. func_args[i] = ConvertArgToDevice(args[i], devices[i], allocators[i]);
